window.RP_SESSION={"id":"S-ef5e379367d6","messages":[{"id":"RP-0246445","time":"2026-08-22T03:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"때는 맥도귈을 찾기 위해 허그와 뻬르난떼, 둘이 땅굴에서 여차저차 한 후 모든 일이 끝난 그날 밤.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246446","time":"2026-08-22T04:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 침대에 엎드려 얼굴을 박고 잠시 이래저래 생각들을 하고있습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246447","time":"2026-08-22T04:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"궁금한 점들이 아직 너무나도 많지만, 당장 오늘은 서로가 지친 듯 하여 이만 들어가 보기로 했었지만요, 허그는 역시나 잠이 오질 않습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246448","time":"2026-08-22T04:02:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"분명 허그가 사람들을 데리고 굴에서 먼저 벗어났을 때, 허그의 시야에서의 마지막까지 거미들로부터 일행들을 지켜주던 뻬르난떼의 몰골은 처참했었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246449","time":"2026-08-22T04:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"오금이 뜯어먹히고, 온 몸을 거미들이 휘감았으며, 처절하게 발버둥치고 땅을 기는 것이 분명 살아남을 사람의 모습은 아닐 것이라 생각했었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246450","time":"2026-08-22T04:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇지만 그 모든 일들이 무색하게도, 허그가 느꼈던 그 절망감들은 별것도 아닌 듯이, 쭈그러 앉아 멍을 때리던 허그를 일어나도록 만든 것은 여태까지와 같은 특이한 말투와 멀쩡한 덩치로 그 자리에 나타난, 온전한 뻬르난떼 경이었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246451","time":"2026-08-22T04:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"물론 그리 팔팔해 보인다 그정도 까지는 아니었습니다. 분명 아직 모험에서의 상처가 남아있는 것인지 허그의 약한 주먹질에도 멋들어진 반응들을 보여줬었거든요.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246452","time":"2026-08-22T04:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…그래서 어떻게?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246453","time":"2026-08-22T04:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"뻬르난떼 경이 회복 요술을 쓸 줄 알던가? 아닙니다. 땅굴에 우리 말고도 다른 치료사가 남아있었나? 전혀요, 고치란 고치는 전부 까뒤집고 다닌 바람에 허그의 몸이 난장판이 됬었습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246454","time":"2026-08-22T04:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"역시나 뭔가 이상하지만…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246455","time":"2026-08-22T04:10:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이제 여기까지. 허그는 이것에 대한 생각은 여기서 멈추기로 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246456","time":"2026-08-22T04:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"더이상의 머리 아픈 생각은 싫기도 하고, 무엇보다 허그의 머리로 이런 생각들을 하는 것에 시간을 들이는 것 보단야, 어떻게던 뻬르난떼 경이 살아있는 채로 함께 돌아온 것에 대해 기뻐하는게 지금으로써는 가장 멋들어진 대처였거든요.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246457","time":"2026-08-22T04:13:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"무엇보다 가장 궁금한 것은 따로 있으니 말이죠.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246458","time":"2026-08-22T04:14:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"얼마전, 구출한 사람들을 데리고 모두 함께 밖으로 빠져나가고자 하던 그 때.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246459","time":"2026-08-22T04:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"뻬르난떼 경은 모두의 부름에도 묵묵히 자리를 지켰습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246460","time":"2026-08-22T04:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”어째서? 분명 곧바로 따라와도 됬었을거 아니야, 내가 그렇게 약한 편도 아니고… 조금 위험했어도 그러질 않으면 도저히 경이 무사할 수가 없었을텐데…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246461","time":"2026-08-22T04:16:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그리고 아니나 다를까, 결국 뻬르난떼 경은 점점 무너져만 갔고, 허그에게는 선택의 순간이 찾아오고야 말았습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246462","time":"2026-08-22T04:19:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"저 아래서 우리를 위해 온 몸을 기고 구르며 열심히 저항하여 녀석들을 막아내고 있는, 허그의 식구이자 두터운 믿음을 가진 뻬르난떼 경을 구해야 할까?\n방금 처음 본 사이이며 단 한번의 일면식도 없었고, 그저 지금 상황에서 발목을 붙잡는 중인 병자 하나와 순박한 의사. 이 둘을 구해야 할까?","characters":["P-6a1a99e98a44"]},{"id":"RP-0246463","time":"2026-08-22T04:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"분명 허그는 당연히 뻬르난떼 경을 생각했습니다.\n당연하지 않습니까? 아무리 이 둘을 구하기 위해 그동안 많은 고생을 했었다고 해도, 지금 허그가 나서질 않으면 눈앞에서 경이 죽어버릴 것만 같은데.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246464","time":"2026-08-22T04:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇지만 허그는 그러지 않았습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246465","time":"2026-08-22T04:21:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"우선, 망설였습니다.\n둘 중 누구를 구해야 할까?","characters":["P-6a1a99e98a44"]},{"id":"RP-0246466","time":"2026-08-22T04:21:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그리고 떠올렸습니다.\n분명 뻬르난떼 경이라면 이 둘을 올려보내고자 했을거야.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246467","time":"2026-08-22T04:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고선 역시나, 그에게서 이러한 말을 듣게 되었죠.\n자신은 괜찮으니 저 둘을 데리고 나가달라고. 정말 자신은 괜찮을테니.\n…허그는 이때의 상황을 다시금 떠올리며, 입술을 꽉 깨물고 얕은 웃음을 내뱉습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246468","time":"2026-08-22T04:23:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하, 정말이지… 다시 생각해봐도 모르겠단 말이야……”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246469","time":"2026-08-22T04:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그 이후는 마찬가지로 아까와 같습니다.\n허그는 결국 둘을 이끌고 밖으로 나갔으며 경을 사실상 버려두었죠.\n어째서? 정말 왜 그랬던거지?\n자신의 식구들을 아끼길 막 배운 허그는, 당연히 여태까지와 같이 그리 하기로 했었지만, 이 식구는 달랐습니다.\n본인의 목숨이 달린 이 판에서, 오히려 남을 구하고자 했습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246470","time":"2026-08-22T04:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그래서 이걸 떠올리면 어쩔겁니까?","characters":["P-6a1a99e98a44"]},{"id":"RP-0246471","time":"2026-08-22T04:27:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…프후……“\n\n…\n\n”여이, 이거 안물어보곤 못베기겠는걸.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246472","time":"2026-08-22T04:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"혼란스럽습니다. 너무나도 혼란스러울 뿐이니…\n음, 그냥 차라리 시원하게 물어봅시다.\n\n아무래도 말이야, 혼자 끙끙대는건 나한테 안맞는다니깐.\n기다려 경~ 지금 그리로 갈테니까.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246473","time":"2026-08-22T04:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 방을 나섭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246474","time":"2026-08-22T04:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0246475","time":"2026-08-22T04:29:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"다음을 기대할게..!","characters":[]},{"id":"RP-0246476","time":"2026-08-22T04:37:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…프하하. 그러고 보니 아까 허리도 무지하게 아팠을텐데 말이야. 가는 김에 그거도 좀 물어보고 그래야겠는걸~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246477","time":"2026-08-22T04:37:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"진짜 끗!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246478","time":"2026-08-22T04:37:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0246479","time":"2026-08-22T04:37:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"...good for you.","characters":[]},{"id":"RP-0246631","time":"2026-08-23T01:28:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"저벅 저벅~","characters":["P-6a1a99e98a44"]},{"id":"RP-0246632","time":"2026-08-23T01:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 두 발을 이끌고 열심히 복도를 걷습니다!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246633","time":"2026-08-23T01:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"계단을 내려가고, 조금 더 걸어서…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246634","time":"2026-08-23T01:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"쿵쾅쾅쾅콰쾅콰콰쿼콰쾅","characters":["P-6a1a99e98a44"]},{"id":"RP-0246635","time":"2026-08-23T01:30:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여~이 뻬르난떼 경~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246636","time":"2026-08-23T01:30:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"두드리는건 요란해도 말은 조용히 하니 세잎!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246637","time":"2026-08-23T01:31:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"헉 그러고보니","characters":["P-6a1a99e98a44"]},{"id":"RP-0246638","time":"2026-08-23T01:31:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"거인이다! 거인이 여왕폐하의 길드를 공격하고 있다! 모든 장정들은 곁에 있는 물건, 무기, 혹은 나무 의자 같은 것이라도 들고 전투에 돌입하라! 이는 역사적인 순간이며, 그 숭고한 희생은 결코 잊혀지지 않으리니!\"\n\n뻬르난떼는 공습 경보! 공습 경보! 를 외치며, 한동안 뛰어다니다가 허그의 인삿말에 그제서야 문을 열었다.\n\n\"아! 공주님! 반갑습니다. 잠시 간악한 거인이 저희 여왕폐하의 길드를 공격 하는 바람에 제가 그 거인을 무찌르기 위한 크나 큰 노력을 하고 있었나이니. 실례가 안된다면 이 누추 한 방에 공주님을 초대 해 드리도록 하겠나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246639","time":"2026-08-23T01:32:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"뻬르난떼 경과 브로크씨가 우연히 같은 방이군요. 조용히 해요 허그!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246640","time":"2026-08-23T01:33:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“오! 이 밤중에도 바쁘구만~ 내가 방해한건 아닌가 모르겠네.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246641","time":"2026-08-23T01:34:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"공주님이 훗날 어느 달밤에 갑작스럽게 들어오신다 하더라도 이는 필히 경비가 제 일을 하고 있는지를 확인하고 있는 것이나 다름이 없을 터 이오니. 어찌 올바른 일을 늦은 밤에 한다고 해서 말릴 자가 있겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246642","time":"2026-08-23T01:35:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 그런건가? 그럼 어디, 우리 뻬르난떼 경은 일을 잘 하고 있었나 들어가봐야겠는걸.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246644","time":"2026-08-23T01:36:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 거대한 뻬르난떼의 너머로, 방을 슬쩍 훑어봅니다…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246645","time":"2026-08-23T01:36:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다 공주님!\"\n\n뻬르난떼는 격식 있고, 예의 있는 자세로 문을 열며, 허그를 방 안으로 소개시켰다.\n\n...그곳에는 뻬르난떼를 제외한 그 누구도 없었고, 자세히 보니 천장이 뻬르난떼의 키를 감당하기에는 살짝 부족 해 보이는듯 했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246646","time":"2026-08-23T01:38:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 사양않고.”\n\n허그는 뻬르난떼의 안내에 따라 방 안으로 들어섭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246647","time":"2026-08-23T01:40:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"공주님을 위하여 차를 우려드리고 싶으나, 안타깝게도 본디 편력 기사는 사치를 해서는 안되는 법. 그러한 연유로 제가 가진 물을 드리도록 하겠나이다.\"\n\n이후로 뻬르난떼는 의자를 갖고와서 허그를 앉혔고, 자신 또한 의자에 앉았다.\n\n...뻬르난떼가 의자에 앉으니 마치 장난감 의자에 어거지로 앉은 듯한 느낌이 들을 수준으로 뻬르난떼는 너무 컸다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246648","time":"2026-08-23T01:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 의자에 앉았습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246649","time":"2026-08-23T01:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"착-","characters":["P-6a1a99e98a44"]},{"id":"RP-0246650","time":"2026-08-23T01:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고는 잠시 멍…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246651","time":"2026-08-23T01:41:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"물어볼 것들을 정리중입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246652","time":"2026-08-23T01:42:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"실례지만, 공주님께서는 어떠한 연유로 저의 방이자 저의 공간에 들어오시게 됐습니까? 말동무가 필요하시다면 저 돈 뻬르난떼 데 일리아는 말할 이야기거리들이 매우 많으니. 필히 시간 가는줄도 모르실 터 이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246653","time":"2026-08-23T01:43:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“음! 그거 괜찮은걸~ 다음에도 심심하거나 그러면 경한테 한번씩 찾아가야겠어.\n그래도, 지금은 그거 때문에 온 건 아니니까 말이야.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246654","time":"2026-08-23T01:44:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"알겠습니다 공주님.\"\n\n뻬르난떼는 그럼 평소에 왜 나를 찾아오셨었던 거지? 라는, 뻬르난떼 답지 않은 생각을 했었으나, 이내 자신이 멋져서 라는 답을 도출 해 냈다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246655","time":"2026-08-23T01:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“있잖아, 경은 오늘 그 땅굴에서 거미 녀석들로부터 우릴 지켜줬을 때 말이야,\n사실 무지하게 위험한 지경까지 갔었지?\n내가 봐도 어딘가 많이 위험해보이는 그런 모습이었으니까 아무래도.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246656","time":"2026-08-23T01:47:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다 공주님! 그때의 저는 위협속에 노출된 여타 다른 매체에 등장했었던 편력 기사의 모습이었습니다! 아, 이 어찌나 영웅적이고 감동적인 모습이 아닐 수가 없겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246657","time":"2026-08-23T01:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그래그래, 굉장했었다고. 엄청나게 말이야.\n정말 아무렇지도 않은 것처럼 녀석들한테 뜯겨나가면서도, 끝까지 경의 그런 말투로 그런 말들을 하다니… 이만큼 멋들어진 사람을 여태까지 본 적이 없었다고, 여이.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246658","time":"2026-08-23T01:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“근데 있잖아 뻬르난떼 경,\n나 궁금한게 있어.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246659","time":"2026-08-23T01:51:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"이리도 적극적으로 칭찬을 해 주시다니! 공주님의 그 아리따우신 온정과 오늘의 날은 결코 잊지 않도록 하겠나이다.\"\n\n뻬르난떼는 허그의 손등에 입맞춤을 하려다가, 이내 허그의 질문을 들으려 하기 시작했다.\n\n\"궁금하신게 있으시다면 말씀을 하시는것이 인지 상정. 무엇이던지 물어보신다 하더라도 다 말해주도록 하겠습니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246660","time":"2026-08-23T01:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그 말이 끝나자, 허그는 자리에서 슬쩍 일어나 바닥에 한쪽 무릎을 꿇습니다.\n\n그러고선 아직도 건드릴 때마다 미세하게 떨어대는 경의 아픈 허리부를 한 손으로 살짝 움켜쥐고, 고개를 들지 않고 그곳을 계속 응시하며 조용히 말을 이어갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246661","time":"2026-08-23T01:54:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"카앍!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246662","time":"2026-08-23T01:55:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”프하하…“\n\n…\n\n”경은 있잖아, 오늘 구해준 그 사람들과 한 번이라도 마주친 적이 있었어?“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246663","time":"2026-08-23T01:56:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"당연히 없습니다 공주님! 저와 공주님은 환대를 받았을때에도 같이 왔고, 길드에 돌아왔을때에도 같이 돌아왔나이니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246664","time":"2026-08-23T01:56:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"공주님이 마주치신 적이 없다 하신다면 당연히 저 또한 없는 것이 인지상정이고, 제가 마주친적이 없다 하면 공주님 또한 마주치지 못하셨을 것이지요.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246665","time":"2026-08-23T01:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그니까 말이야.\n그러면? 한 녀석은 먼저 도망쳐버리고, 뻬르난떼 경도 심하게 다치고, 그 약한 녀석들이 이후에 우리한테 마땅한 보수나 그런걸 줄 수도 없을텐데…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246666","time":"2026-08-23T01:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 고개를 듭니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246667","time":"2026-08-23T01:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“왜 나한테도 그녀석들을 도우라고 그랬어?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246668","time":"2026-08-23T01:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“왜 그렇게까지 한거야 경은?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246669","time":"2026-08-23T02:00:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님. 그것은 바로 생명의 무게란 무릇 결코 가볍지 아니하기 때문이옵니다. 생명은 요컨대 이 세상의 모든 부를 가져온다 하더라도 비교선상에 두기는 커녕 저울질 조차 하지를 못할 정도의 값어치를 지니고 있으며, 생명이 주는 그 아름다움과 그 가능성은 결코 이루 말할 수 없을 것이옵니다.\"\n\n뻬르난떼는 다시 말을 이어서 하려 하기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246670","time":"2026-08-23T02:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼를 이해하기 위해 이 자리를 만든 것이기에, 이번엔 별 말 없이 들어보고자 합니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246671","time":"2026-08-23T02:02:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"가령 제가 살려준 그 의사가 어느날 여러 대륙에서 도는 아주 고약하고, 심각한 역병을 치료하는 치료제를 개발 할 지도 모르는 일이롭고, 제가 구해준 여인이 낳은 아들, 혹은 딸이 세상의 악을 무찌르고, 이루 말하지 못할 영웅적인 일을 할 지도 모르는 법이지요. 그러한 이유가 아니라 하더라도 저 또한 이 세상에 한명밖에 없듯이, 저 생명, 특히 지능을 가지고 있는 인간 또한 이 세상에 한명밖에 없는 것이 아니겠습니까? 그러한 연유로 저는 소중한 공주님의 목숨과 또 다른 소중한 목숨들을, 모든 이들을 구하기 위하여 가장 합리적인 답안을 도출 해 낸것이라 보면 됄 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246672","time":"2026-08-23T02:03:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"만물의 아버지이자 어머니이신 라운데라님께서 창조하신 생명의 값어치와 그러한 생명을 창조 해 내신 라운데라님께서는 저의 생명 또한 기필코 중히 여길것임이 분명하기에, 저는 죽지 않을 것이라는 확신과 그 용기에 두려움속에서도 맞서 싸울 수 있었던 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246673","time":"2026-08-23T02:03:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"달리 말하자면, 이는 용기가 아닌 광기라 봐도 무방 할 것이었지만, 적어도 뻬르난떼는 이를 용기라고 생각하고 있는 것 같아 보였다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246674","time":"2026-08-23T02:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246675","time":"2026-08-23T02:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하, 역시나 경은 이번에도 그렇게 말해주는걸.“\n\n허그는 작게 웃어보입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246676","time":"2026-08-23T02:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러다가…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246677","time":"2026-08-23T02:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그러면 말이야…… 그러면……“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246678","time":"2026-08-23T02:06:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼의 허리를 붙잡던 손을 스르르 떼고…\n이내 주먹을 꽉 쥐어서","characters":["P-6a1a99e98a44"]},{"id":"RP-0246679","time":"2026-08-23T02:06:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!힘","characters":["P-6a1a99e98a44"]},{"id":"RP-0246680","time":"2026-08-23T02:06:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 힘 판정 :\n[12] + [2] = [14]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0246681","time":"2026-08-23T02:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"뻬르난떼의 다친 곳을 매우 약하게, 여태까지 그 어느때보다도 약하게 툭-\n주먹질 하여 칩니다.\n\n아마 뻬르난떼는 그 어떠한 통증도 느껴지지 않았을 겁니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246682","time":"2026-08-23T02:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고는…\n\n뚝.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246683","time":"2026-08-23T02:08:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"?\"\n\n뻬르난떼는 갸우뚱 거린채로, 허그를 쳐다봤다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246684","time":"2026-08-23T02:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"투둑… 뚝…\n\n뻬르난떼의 저 아래에서, 허그가 웁니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246685","time":"2026-08-23T02:10:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"...공주님?\"\n\n뻬르난떼는 조심스럽게 허그를 불렀다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246686","time":"2026-08-23T02:11:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 한동안 눈물을 조금씩 흘리다가, 어렴게 말을 이어갑니다.\n\n\n“…제기랄, 그러면 경의 말대로 그 좋은일 하는거 나도 같이 하게 해줬으면 좋았잖아……”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246687","time":"2026-08-23T02:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“왜 도와달라고 그러지 않은거야? 꼭 경 혼자서 그자식들을 막아야만 우리가 무사하게?\n경은 나를 못믿어? 나 가델랏 허그라고……“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246688","time":"2026-08-23T02:13:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”난 지금도 모르겠단 말이야, 내가 멍청한건지, 그냥 오늘따라 유독 경이 너무나도 굉장해 보였던 건지, 경의 그런 말을 결국 그대로 따라서는…… 경을……”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246689","time":"2026-08-23T02:14:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“난 경이 죽을 줄 알았다고…… 그렇게 알았는데도…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246690","time":"2026-08-23T02:15:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론, 저는 공주님을 믿습니다. 허나, 공주님께서 그들을 도와주지 않았더라면 그 탈진한 의사가 여인 한분을 든 채로 어찌 그토록 끔찍한 굴을 나올 수 있었겠습니까? 제가 공주님에게 그리 부탁드린 것은 공주님을 그 누구보다도 믿었기 때문이옵니다. 또한 저의 바램대로, 그리고 공주님의 바램대로 저와 여인, 그리고 의사와 공주님까지 몸 성히 돌아오실 수 있으시지 않으셨습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246691","time":"2026-08-23T02:17:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그렇기 때문에 제가 그러한 결정을 내리신 것이였습니다. 공주님이 제 아무리 강력하셔도 그 마물들의 쪽수는 기필코 상상을 초월하는 것이었고, 공주님의 신변 또한 위험 하실 수 있었으며, 그 여인의 상태가 심히 걱정됐기 때문이었으니. 저는 결코 거짓말을 하지 않는 편력 기사이옵니다. 그러니 이리 무사하게 돌아온것이 아니겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246692","time":"2026-08-23T02:20:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…이상하네. 분명 그땐 정말… 다 무너져버릴 것 같았었는데…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246693","time":"2026-08-23T02:21:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…하하,\n여이. 결국엔 이번에도 경의 말대로 되버렸잖아.\n이쯤되면 정말 뻬르난떼 경은 요술쟁이인거 아니야?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246694","time":"2026-08-23T02:22:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"저의 언변과 저의 능력은 가히 만물의 아버지이자 어머니이신 라운데라님께서 지켜보고 계신 만큼, 또한 편력 기사인만큼 요술이나 다름 없어야만 하옵니다. 또한 편력 기사는 본디 불가능에 도전을 해야 하는 자 이오니. 그 역경과 고난속에 끝내 불가능과 맞서싸워 이긴 편력 기사들을 요술이라 보신다 하더라도 결코 이상하지 않을 것이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246695","time":"2026-08-23T02:23:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그러니 공주님. 저를 걱정하실 필요가 없습니다. 저는 결코 죽지 않는, 쓰러지지도 않는 무적의 편력 기사이니 말이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246696","time":"2026-08-23T02:24:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“…여이, 무적의? 정말로?“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246697","time":"2026-08-23T02:24:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그가 굽힌 무릎을 일으킵니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246698","time":"2026-08-23T02:25:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"당연합니다 공주님! 제가 무적이 아니라면 그 어떠한 편력 기사를 무적이라 일컫을 수 있겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246699","time":"2026-08-23T02:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 한동안 뻬르난떼를 가만히 응시하다가…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246700","time":"2026-08-23T02:26:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”푸하!!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246701","time":"2026-08-23T02:27:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 됬어. 그 말이 무지하게 필요했었다고?”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246702","time":"2026-08-23T02:27:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“결국엔 역시 뻬르난떼 경이니까 그랬던 거네~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246703","time":"2026-08-23T02:28:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"물론이옵니다 공주님! 제가 아니라면 다른 겁쟁이들과 같은 이들은 가히 상상도 못할 선택지임은 자명합니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246704","time":"2026-08-23T02:29:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하, 이래서야 말이지, 분명 방금까지는 머릿속이 엄청나게 꽉 들어찬 것 같았었는데 말이야.\n이상하게도 뻬르난떼 경의 그런 말을 들으니까 전부 사라졌는걸.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246705","time":"2026-08-23T02:30:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 급하게 눈물을 슥슥, 붉어진 눈시울의 얼굴로 여느때와 같이 밝에 웃어봅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246706","time":"2026-08-23T02:31:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그러니 공주님. 눈물을 그쳐 주시옵소서. 여인을 울리는 것 또한 기사도에 위배되는 행위이노니. 저 편력 기사인 돈 뻬르난떼 데 일리아는 공주님의 눈물을 닦아드릴 의무가 있습니다.\"\n\n뻬르난떼는 손을 조심히 뻗어 허그의 눈물을 닦아줬다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246707","time":"2026-08-23T02:32:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”끄아~ 방금 이미 닦았단 말이야~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246708","time":"2026-08-23T02:32:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246709","time":"2026-08-23T02:33:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”푸하하!\n여이, 경. 잠깐 일어나봐~“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246710","time":"2026-08-23T02:33:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"공주님의 말씀이라면 응당 따르겠습니다.\"\n\n뻬르난떼는 잠시 의자에서 일어났다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246711","time":"2026-08-23T02:35:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그러고선…\n\n포옥-\n\n허그는 뻬르난떼의 품으로 들어가 이내 깊게 끌어안습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246712","time":"2026-08-23T02:36:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“난 그러면 경을 쭉 믿을래.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246713","time":"2026-08-23T02:36:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"뻬르난떼 또한 허그를 안아줬다.\n\n\"공주님의 성 답게 공주님께서는 포옹을 좋아하시는군요! 본디 포옹이란 인간의 화를 낮추고, 평온함을 주는 일이오니. 이리도 긍정적이고, 효과 좋은 일에는 응당 따라드려야 하는 것이 편력 기사의 도리일 터.\"\n\n뭔가 시끄럽게 나불대기는 했지만, 아무튼 장면만 본다면 심히 감동적일 것이었다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246714","time":"2026-08-23T02:37:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"좋습니다 공주님! 저를 믿고 따라주신다면 저는 천군 만마를 얻은 것이나 다름이 없으니! 이 무한한 은혜에 감사를 드릴 따름이옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246715","time":"2026-08-23T02:39:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“세삼스럽게 이렇게 말하기엔 이미 그러고 있지만 말이야, 역시 난 경을 믿는게 좋은 것 같아! 그러니까 앞으로도 쭉 믿을래. 오늘처럼 무지하게 무서운 날이 있어도, 앞으로는 뻬르난떼 경이 그런다면 나는 믿을거라고.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246716","time":"2026-08-23T02:39:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”역시 그 편이 좋은걸, 여이!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246717","time":"2026-08-23T02:40:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼의 차가운 갑옷에 이마를 맞대며, 이렇게 말했습니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246718","time":"2026-08-23T02:40:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"무서운 것을 저 멀리 보내고, 선한 것을 구하며, 악한 자들을 물리치고, 무고한 이들을 구해 주는것이 저의 사명이노니. 공주님의 기대에 언제든지 응 해 드릴 수 있는 편력 기사로서 더욱 전진하도록 하겠나이다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246719","time":"2026-08-23T02:44:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그러면 나 또한 뻬르난떼 경의 그런 멋들어진 모험들을 함께 하고, 내가 필요할땐 언제든 경의 옆에서 믿고 도와줄테니~ 그런 편력 기사 뻬르난떼 경이 더 더 믿을 수 있도록 힘내는 그런 가델랏 허그가 될 것이다. 일려나!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246720","time":"2026-08-23T02:45:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”그럼 있잖아 경, 우리 그거 해야지? 저번에 경이 알려줬었던 그거 있잖아.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246721","time":"2026-08-23T02:46:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"좋은 각오입니다 공주님! 원하신다면 공주님 또한 저의 종자로 삼아드릴수도 있을 것이오나, 비록 본디 기사가 여럿의 종자를 이끌고 다닌다 하더라도 본래에 있었던 종자인 맥도귈의 허락을 받는 것이 인간의 도리일 것이노니.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246722","time":"2026-08-23T02:46:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼의 품에서 빠져나와, 가만히 뻬르난떼를 바라봅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246723","time":"2026-08-23T02:46:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아! 공주님의 손등에 입맞춤을 해 드리는 것이옵니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246724","time":"2026-08-23T02:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하, 그건 이미 받았잖아? 그니까…“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246725","time":"2026-08-23T02:47:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼의 손을 끌고 와, 그때처럼 무릎을 꿇…기에는 키가 안닿으니 그냥 서서.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246726","time":"2026-08-23T02:48:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"달그락- 뻬르난떼의 오른손의 장갑을 빼낸 후, 조심스레 그 손을 들고는.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246727","time":"2026-08-23T02:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"서로에게 믿음을 보인, 뻬르난떼 경의 여정에 허그가 도움을 주고자 함께 하기로 했던 호수에서의 그날처럼","characters":["P-6a1a99e98a44"]},{"id":"RP-0246728","time":"2026-08-23T02:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"입을 맞","characters":["P-6a1a99e98a44"]},{"id":"RP-0246729","time":"2026-08-23T02:49:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"맞, 맞… 맞춥…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246730","time":"2026-08-23T02:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"이런, 허그는 누군가에게 입을 맞추어 본 적이 없습니다!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246731","time":"2026-08-23T02:50:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“으벱, 업, 여이, 잠깐만 기다려봐, 이거 생각보다 어째…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246732","time":"2026-08-23T02:51:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"삐쭉삐쭉… 덤벙거리는 허그…!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246733","time":"2026-08-23T02:52:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님께서 저의 손등에 입맞춤을 해 주시다니! 어찌도 이리 감사 할수가! 중요한것은 공주님께서 저의 손등에 입맞춤을 해 주신 것이오니.\"\n\n이후 뻬르난떼는 자신의 손을 천천히 올리면서. 허그의 입술에 자신의 손을 갖다댔다.\n\n\"감사합니다 공주님.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246734","time":"2026-08-23T02:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“웁-”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246735","time":"2026-08-23T02:53:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“끄아, 아하이 진짜! 이번엔 내가 알아서 해볼려고 했었는데 말이야…”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246736","time":"2026-08-23T02:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“거의 다 왔었다고~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246737","time":"2026-08-23T02:54:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 뻬르난떼를 다시 바라봅니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246738","time":"2026-08-23T02:54:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"그렇다면 이제 감각을 알게 되셨으니 다시 해 보시겠습니까?\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246739","time":"2026-08-23T02:56:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”엥? 여이, 뻬르난떼 경 욕심이 많은거 아니야~ 이미 한 번 했으니까 두 번은 안된다고. 나도 한 번 받았으니까 뻬르난떼 경도 한 번!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246740","time":"2026-08-23T02:57:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님께서 그리 말씀하신다면 그리 하도록 하겠나이다.\"\n\n뻬르난떼는 다시 한번 예의있고, 격식있는 자세로 무릎을 꿇은 뒤, 허그의 손에 입을 맞추려 하기 시작했다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246741","time":"2026-08-23T02:58:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"!민첩","characters":["P-6a1a99e98a44"]},{"id":"RP-0246742","time":"2026-08-23T02:58:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"'가델랏 허그'의 민첩 판정 :\n[9] + [3] = [12]\n결과 : 완벽한 성공, 운명은 당신의 편입니다.","characters":[]},{"id":"RP-0246743","time":"2026-08-23T02:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“여이, 과연~!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246744","time":"2026-08-23T02:59:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"텁-","characters":["P-6a1a99e98a44"]},{"id":"RP-0246745","time":"2026-08-23T03:00:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 재빨리 뻬르난떼의 다른 손을 끌어다가, 자신의 손 위로 감싸 뻬르난떼의 입맞춤 공격을 막아냈습니다. 여이!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246746","time":"2026-08-23T03:01:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"! 역시. 공주님의 속도는 능히 제가 범접할수가 없군요...\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246747","time":"2026-08-23T03:01:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“하하하, 오늘은 이만 시간도 늦었고 말이야.\n무엇보다 이미 내가 했으니까 경이 진거라고? 그러면 진 뻬르난떼 경은 다음 기회를 노려야지 아무래도~”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246748","time":"2026-08-23T03:02:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"공주님의 뜻이 그러하시다면야. 알겠습니다 공주님. 공주님도 오늘 밤 잠을 잘 주무시길 바라옵니다.\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246749","time":"2026-08-23T03:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”여이, 그래!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246750","time":"2026-08-23T03:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 허그는 뻬르난떼에게서 벗어나 다시 기숙사의 문 쪽을 향해…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246751","time":"2026-08-23T03:03:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“아 참.”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246752","time":"2026-08-23T03:04:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그는 그러고는 다시 뒤돌아서, 뻬르난떼에게로 투타타 다가간 다음","characters":["P-6a1a99e98a44"]},{"id":"RP-0246753","time":"2026-08-23T03:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"슥슥…","characters":["P-6a1a99e98a44"]},{"id":"RP-0246754","time":"2026-08-23T03:05:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"자신의 망토를 벗어 뻬르난떼의 손에 올려둡니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246755","time":"2026-08-23T03:07:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“이제 뻬르난떼 경이랑 나는 무슨 일이 있어도 무조건 서로 믿어주는 진짜 친구니깐 말이야.\n우리 길드에서도 식구들한테 뱃지를 나눠주는 것 처럼 말이지, 나도 경한테 이걸 줄게.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246756","time":"2026-08-23T03:08:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"아, 공주님의 중요하신 물건을 저에게 맞겨주신다니! 공주님의 말씀대로. 여왕폐하께서 주신 뱃지처럼. 제 목숨을 다하여 사수하도록 하겠나이다. 이 망토야말로 저에게 있어선 전쟁터의 깃발이요, 가문의 문양이나 다름 없으니!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246757","time":"2026-08-23T03:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”나름 아끼는 망토라고? 밖에 나갈땐 거의 항상 걸치고 다니는 거니깐 말이야, 우리 멋들어진 뻬르난떼 경한테 이정도면 충분하겠지!“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246758","time":"2026-08-23T03:08:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"”하하하! 그거 고마운걸.“","characters":["P-6a1a99e98a44"]},{"id":"RP-0246759","time":"2026-08-23T03:09:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"“그러면 이만 나는 진짜 가볼테니까 말이야, 경 좋은 꿈 꾸고!”","characters":["P-6a1a99e98a44"]},{"id":"RP-0246760","time":"2026-08-23T03:09:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"멋진 편력 기사에게 멋진 물건이 쥐어졌으니! 공주님의 말씀대로입니다!\"","characters":["P-1a1afae9c8db"]},{"id":"RP-0246761","time":"2026-08-23T03:10:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"\"부디 평온한 밤이 되시길 바라도록 하겠나이다...\"\n\n뼤르난떼는 허그가 안 보일때까지 손을 흔들기 시작했다.\n\n본래라면 격식있게 인사를 했을 뻬르난떼였지만... 이런 뻬르난떼의 모습은 마치 무언가 다른 사람과 같아 보였다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246762","time":"2026-08-23T03:12:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"허그도 방에서 나와 복도를 걸어가면서도 쭉 뻬르난떼 쪽을 바라보며 열심히 손을 흔들었습니다.\n\n“끄악-”\n\n이런, 그러다가 반대편 벽에 살짝 부딪히긴 했지만 말이죠. 이내 다시 웃어보이며 이내 뻬르난떼의 시야에서 벗어나는 허그입니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246763","time":"2026-08-23T03:13:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"그렇게 뼤르난떼와 허그의 늦은 밤 밀회는 끝이 났다.\n\n...길드원 사이에서 이상한 소문들이 퍼지고 있는 것 같기는 했지만 말이다.","characters":["P-1a1afae9c8db"]},{"id":"RP-0246764","time":"2026-08-23T03:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"참 정신없는 하루였습니다. 낮에는 무지하게 절망적이었다가도 이내 금방 괜찮아지고, 방에 들어선 뒤 잠을 청하려다가도 머릿속이 복잡해져 결국 뻬르난떼 경의 방에까지 찾아가버렸으니 말입니다.\n그래도, 시작은 미미했으나 그 끝은 창대하였나이니! 오늘의 하루도 멋들어진 끝을,","characters":["P-6a1a99e98a44"]},{"id":"RP-0246765","time":"2026-08-23T03:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그거해요 그거 뻬르난떼!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246766","time":"2026-08-23T03:15:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"끝이 좋으면!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246767","time":"2026-08-23T03:16:00+09:00","room":"RP","name":"돈 뻬르난떼 데 일리아","profile":"피에르","identity":"reviewed","type":"dialogue","body":"다 좋은 법!","characters":["P-1a1afae9c8db"]},{"id":"RP-0246768","time":"2026-08-23T03:16:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"그렇게 돈허그는 오늘도 반발짝 나아갑니다.","characters":["P-6a1a99e98a44"]},{"id":"RP-0246769","time":"2026-08-23T03:16:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"끗!","characters":["P-6a1a99e98a44"]},{"id":"RP-0246770","time":"2026-08-23T03:16:00+09:00","room":"RP","name":"가델랏 허그","profile":"가델랏 허그","identity":"reviewed","type":"dialogue","body":"-fin","characters":["P-6a1a99e98a44"]},{"id":"RP-0246771","time":"2026-08-23T03:16:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"\"아주 멋진 한판이었어!\"","characters":[]},{"id":"RP-0246772","time":"2026-08-23T03:29:00+09:00","room":"RP","name":"발린 호프","profile":"발린 호프","identity":"unresolved","type":"dialogue","body":"!모닥불","characters":[]},{"id":"RP-0246773","time":"2026-08-23T03:29:00+09:00","room":"RP","name":"판정·진행 봇","profile":"《운명의 굴레》","identity":"bot","type":"bot","body":"모닥불에 불씨가 옮겨 붙습니다.\n따뜻한 온기가 피어오릅니다.\n\n ♩ https://youtu.be/3GNyTB6p6i0?si=4L6Rg34M-gtWRqUj","characters":[]}]};
